33	public class CoreBlockEntity extends BlockEntity {
34	  private static final int RESCAN_INTERVAL = 20;
35	
36	  private ScanResult<BlockPos> lastScan =
37	      new ScanResult<>(Problem.WAITING_FOR_CHUNKS, null, Map.of());
38	  private @Nullable Multiblock multiblock;
39	  private @Nullable PowerPool power;
40	  private @Nullable FertilizerPool fertilizer;
41	  private @Nullable OutputSink outputs;
42	  private @Nullable MeLink me;
43	  private @Nullable ResourceHandler<ItemResource> items;
44	  private boolean dirty = true;
45	  private boolean poolsStale;
46	
47	  public CoreBlockEntity(BlockPos pos, BlockState state) {
48	    super(MPBlockEntities.CORE.get(), pos, state);
49	  }
50	
51	  public static void serverTick(Level level, BlockPos pos, BlockState state, CoreBlockEntity core) {
52	    if (core.dirty || (level.getGameTime() + core.tickOffset()) % RESCAN_INTERVAL == 0) {
53	      core.scan(level);
54	    }
55	    if (level instanceof ServerLevel serverLevel) {
56	      core.tickPlanters(serverLevel);
57	    }
58	  }
59	
60	  // The pools are null while the core waits for an unloaded chunk, and the planters then keep their
61	  // progress without ticking.
62	  private void tickPlanters(ServerLevel level) {
63	    if (multiblock == null
64	        || power == null
65	        || fertilizer == null
66	        || outputs == null
67	        || !allPartsLoaded()) {
68	      return;
69	    }
70	    MeLink link = onlineMe();
71	    if (link != null) {
72	      power.refillFrom(link);
73	    }
74	    TickContext context =
75	        new TickContext(
76	            level, level.getRandom(), AteBridge.numbers(), power, fertilizer.budget(), outputs);
77	    for (BlockPos pos : multiblock.planters()) {
78	      if (level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
79	        planter.tickFromCore(context);
80	      }
81	    }
82	    if (link != null && (level.getGameTime() + tickOffset()) % MPConfig.ME_INTERVAL.get() == 0) {
83	      outputs.moveExportsInto(link);
84	      fertilizer.topUpFrom(link);
85	    }
86	  }
87	
88	  // This returns the link only while it is online, and a removed link counts as absent and marks
89	  // the pools stale so the next scan rebuilds them without it.
90	  private @Nullable MeLink onlineMe() {
91	    if (me == null) {
92	      return null;
93	    }
94	    if (me.isRemoved()) {
95	      markPoolsStale();
96	      return null;
97	    }
98	    return me.online() ? me : null;
99	  }
100	
101	  // Cores spread their rescans and ME transfers over different ticks by position, so many cores
102	  // don't all work on the same tick.
103	  public int tickOffset() {
104	    return Math.floorMod(worldPosition.hashCode(), RESCAN_INTERVAL);
105	  }
106	
107	  public void markDirty() {
108	    dirty = true;
109	  }
110	
111	  // A pooled block was removed, and a replacement at the same position gives an equal scan result,
112	  // so the next scan must rebuild the pools anyway.
113	  private void markPoolsStale() {
114	    dirty = true;
115	    poolsStale = true;
116	  }
117	
118	  public ScanResult<BlockPos> lastScan() {
119	    return lastScan;
120	  }
121	
122	  public @Nullable Multiblock multiblock() {
123	    return multiblock;
124	  }
125	
126	  public @Nullable PowerPool power() {
127	    return power;
128	  }
129	
130	  public @Nullable FertilizerPool fertilizer() {
131	    return fertilizer;
132	  }
133	
134	  public @Nullable OutputSink outputs() {
135	    return outputs;
136	  }
137	
138	  public @Nullable ResourceHandler<ItemResource> items() {
139	    return items;
140	  }
141	
142	  public MeStatus meStatus() {
143	    return me == null || me.isRemoved() ? MeStatus.NONE : me.status();
144	  }
145	
146	  public boolean allPartsLoaded() {
147	    return level != null
148	        && (multiblock == null || multiblock.all().stream().allMatch(level::isLoaded));
149	  }
150	
151	  @Override
152	  public void onLoad() {
153	    super.onLoad();
154	    dirty = true;
155	  }
156	
157	  private void scan(Level level) {
158	    dirty = false;
159	    boolean rebuild = poolsStale;
160	    poolsStale = false;
161	    ScanResult<BlockPos> result =
162	        StructureScanner.scan(
163	            worldPosition,
164	            pos -> Arrays.stream(Direction.values()).map(pos::relative).toList(),
165	            pos -> typeAt(level, pos),
166	            MPConfig.PART_CAP.get());
167	    if (result.equals(lastScan) && !rebuild) {
168	      return;
169	    }
170	    lastScan = result;
171	    if (result.problem() == Problem.WAITING_FOR_CHUNKS) {
172	      // The multiblock is kept so a structure with an unloaded part pauses instead of unforming,
173	      // while the pools are dropped so nothing touches a block entity in an unloaded chunk.
174	      power = null;
175	      fertilizer = null;
176	      outputs = null;
177	      me = null;
178	      items = null;
179	    } else {
180	      Multiblock previous = multiblock;
181	      multiblock = result.formed() ? Multiblock.from(result) : null;
182	      if (previous != null) {
183	        stopPlanters(
184	            level, previous.planters(), multiblock == null ? List.of() : multiblock.planters());
185	      }
186	      buildPools(level);
187	    }
188	    level.invalidateCapabilities(worldPosition);
189	    setChanged();
190	  }
191	
192	  // No scan runs once the core is gone, so the core stops its planters here, or they would stay
193	  // ACTIVE and GROWING.
194	  @Override
195	  public void preRemoveSideEffects(BlockPos pos, BlockState state) {
196	    if (level != null && multiblock != null) {
197	      stopPlanters(level, multiblock.planters(), List.of());
198	    }
199	  }
200	
201	  private static void stopPlanters(
202	      Level level, List<BlockPos> planters, List<BlockPos> stillFormed) {
203	    for (BlockPos pos : planters) {
204	      if (!stillFormed.contains(pos)
205	          && level.isLoaded(pos)
206	          && level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
207	        planter.stopFromCore();
208	      }
209	    }
210	  }
211	
212	  private void buildPools(Level level) {
213	    if (multiblock == null) {
214	      power = null;
215	      fertilizer = null;
216	      outputs = null;
217	      me = null;
218	      items = null;
219	      return;
220	    }
221	    power =
222	        new PowerPool(
223	            blockEntities(level, multiblock.power(), PowerBlockEntity.class), this::markPoolsStale);
224	    fertilizer =
225	        new FertilizerPool(
226	            blockEntities(level, multiblock.fertilizer(), FertilizerBlockEntity.class),
227	            this::markPoolsStale);
228	    BlockPos mePos = multiblock.me();
229	    me = mePos != null && level.getBlockEntity(mePos) instanceof MeLink link ? link : null;
230	    outputs =
231	        new OutputSink(
232	            blockEntities(level, multiblock.export(), ExportBlockEntity.class),
233	            me,
234	            this::markPoolsStale);
235	    items = DoorwayHandlers.items(fertilizer, outputs);
236	  }
237	
238	  private static <T extends BlockEntity> List<T> blockEntities(
239	      Level level, List<BlockPos> positions, Class<T> type) {
240	    List<T> found = new ArrayList<>();
241	    for (BlockPos pos : positions) {
242	      BlockEntity blockEntity = level.getBlockEntity(pos);
243	      if (type.isInstance(blockEntity)) {
244	        found.add(type.cast(blockEntity));
245	      }
246	    }
247	    return found;
248	  }
249	
250	  private static PartType typeAt(Level level, BlockPos pos) {
251	    if (!level.isLoaded(pos)) {
252	      return PartType.UNLOADED;
253	    }
254	    return level.getBlockState(pos).getBlock() instanceof PartBlock part
255	        ? part.partType()
256	        : PartType.NOT_A_PART;
257	  }
258	}
